// Primitives
int i_uninit;     // Default init (indeterminate if local)
int i_val{};      // Value init (guaranteed 0)

// Aggregates/Classes (Trivial constructor)
struct Config {
    int id;
    bool active;
};

Config c_default; // Default init (members uninitialized if local)
Config c_value{}; // Value init (id=0, active=false)

// Dynamic allocation uses value initialization
int* p_zero = new int{};

// Array initialization (all elements value initialized)
int arr[5]{};     // All 5 elements set to 0
Config arr_c[2]{}; // Both Configs fully zeroed
